-- PO-approved catalog v2. No XP, ranking, legacy-title, or source-record writes.
create schema title_private;
revoke all on schema title_private from public,anon,authenticated;
grant usage on schema title_private to authenticated;

create table title_private.nuri_title_catalog_v2 (
 id text primary key check (id ~ '^[A-Z]{1,2}[0-9]{2}$'),
 name text not null, category text not null, category_label text not null,
 scope text not null check (scope in ('pet','common')),
 domain text not null,
 condition_label text not null,
 hidden boolean not null,
 requirements jsonb not null check (jsonb_typeof(requirements)='array' and jsonb_array_length(requirements)>0)
);
create table title_private.nuri_title_policy_state_v2 (
 singleton boolean primary key default true check (singleton),
 activated_at timestamptz not null default statement_timestamp()
);

create table title_private.nuri_title_awards_v2 (
 user_id uuid not null references auth.users(id) on delete cascade,
 pet_id uuid references public.pets(id) on delete cascade,
 title_id text not null references title_private.nuri_title_catalog_v2(id),
 earned_at timestamptz not null default statement_timestamp(),
 policy_version integer not null default 2 check (policy_version=2),
 reason text not null check (reason in ('rule_v2','legacy_preserved')),
 evidence jsonb not null default '{}'::jsonb,
 unique nulls not distinct (user_id,pet_id,title_id)
);
create index nuri_title_awards_v2_owner on title_private.nuri_title_awards_v2(user_id,pet_id,earned_at desc);
create table title_private.nuri_title_legacy_receipts_v2 (
 user_id uuid primary key references auth.users(id) on delete cascade,
 preserved_at timestamptz not null default statement_timestamp()
);
create table title_private.nuri_title_pet_origins_v2 (
 pet_id uuid primary key references public.pets(id) on delete cascade,
 first_recorded_at timestamptz not null
);
-- Profile dates are observed, not retroactively assumed. A later profile edit
-- cannot make an old record participate in a newly chosen anniversary.
create table title_private.nuri_title_pet_dates_v2 (
 pet_id uuid not null references public.pets(id) on delete cascade,
 observed_at timestamptz not null default statement_timestamp(),
 birth_date date, adoption_date date,
 primary key (pet_id,observed_at)
);
 select id,birth_date,adoption_date from public.pets;
create table title_private.nuri_title_holidays_v2 (
 event_year integer not null check (event_year between 1900 and 2200),
 kind text not null check (kind in ('seollal','daeboreum','chuseok')),
 event_date date not null,
 source_url text not null check (source_url ~ '^https://'),
 verified_at timestamptz not null default statement_timestamp(),
 primary key (event_year,kind)
);
-- Official yearbooks only; an unseeded year never gets an invented lunar date.

create table title_private.nuri_remembrance_records_v2 (
 memory_id uuid primary key references public.memories(id) on delete cascade,
 user_id uuid not null references auth.users(id) on delete cascade,
 pet_id uuid not null references public.pets(id) on delete cascade,
 included_at timestamptz not null default statement_timestamp()
);
create index nuri_remembrance_records_v2_owner on title_private.nuri_remembrance_records_v2(user_id,pet_id);

do $security$
declare t text;
begin
 foreach t in array array['nuri_title_catalog_v2','nuri_title_policy_state_v2','nuri_title_awards_v2',
 'nuri_title_legacy_receipts_v2','nuri_title_pet_origins_v2','nuri_title_pet_dates_v2','nuri_title_holidays_v2','nuri_remembrance_records_v2'] loop
  execute format('alter table title_private.%I enable row level security',t);
  execute format('create policy server_owned on title_private.%I for all to public using(false) with check(false)',t);
  execute format('revoke all on title_private.%I from public,anon,authenticated',t);
 end loop;
end;
$security$;

